# -*- coding: utf-8 -*-
"""Part 2: hacked accounts, Meta Verified, TikTok."""
from c_en1 import *
TTSEND = ['Your TikTok username.', 'A screenshot of the ban or warning, with the date visible.', 'Which email or phone is on the account (just which one, never a code).', 'What happened in the days before.']
fam('tiktok', ws='unban', platform='TikTok', decider='TikTok', parent=HUB, stype='TikTok account appeal help',
    wa='Hey%20Unbanz%2C%20I%20need%20help%20with%20my%20TikTok%20account', subj='TikTok%20account', what='a TikTok account', send=TTSEND,
    how1='your TikTok username and a screenshot of the notice',
    how3='We tell you which of TikTok’s own routes fits and help you prepare what to send.')
fam('legal', **dict(FAM['fbdis'], parent=LEG, stype='Account ban appeal and rights guidance', what='your options after an account ban',
    subj='Account%20ban%20rights', how1='your username, the notice and the date of each decision',
    how3='We help you put the facts in order for the route you choose. This is not legal advice.'))
fam('verified', **dict(FAM['igrecov'], parent=VER, stype='Meta Verified support guidance', what='Meta Verified support'))
fam('hacked', **dict(FAM['ighacked'], parent=HUB))

page('is-this-instagram-security-email-real', 'ighacked', 'Is This Instagram Security Email Real? How to Check',
 'Got an email saying your Instagram email or password changed? How to tell a real security email from a fake one, and the secure link to use.',
 'Is that Instagram security email real or a scam?', 'Real or fake security email',
 'Real Instagram security emails come from instagram.com addresses and also appear inside the app. Fakes push you to log in through a link.',
 'A real Instagram security email comes from an address ending in mail.instagram.com and is also listed in the app under Accounts Center, Password and security, Emails from Instagram. If the email says your email or password was changed and you did not do it, use the secure this account link in that real email straight away.',
 [('Check the sender', 'Real ones end in mail.instagram.com.'), ('Check the app', 'Real emails are listed in Accounts Center.'), ('Act on the real one', 'Use the secure link to undo changes.')],
 [S('How to check',
    ol(['Do not tap any link yet. Look at the full sender address.', 'In the Instagram app open Accounts Center, Password and security, then Recent emails or Emails from Instagram.',
        'If the email is listed there, it is real. If it is not, treat it as phishing and delete it.', 'If you cannot log in, compare the sender and look for the email on another device.'])),
  S('If the change was not you',
    'A real email about a changed email address usually includes a link to revert the change and secure the account. Use it from the original email. Then reset the password, turn on two-factor authentication with an authenticator app, and remove sessions you do not recognise in Where you are logged in. If the link has expired, go to %s.' % A('/guides/hacked-instagram-account-recovery/', 'hacked Instagram account recovery')),
  S('Signs of a fake', ul(['Threats that the account will be deleted within hours.', 'Links to pages that are not instagram.com.', 'Requests for your password, login code or a payment.', 'Copyright or verification badge emails asking you to log in.'])),
 ],
 [('Does Instagram send copyright warnings by email?', 'Copyright removals are shown in the app. Emails or DMs threatening deletion over copyright are a common scam.'),
  ('What if I already entered my password on a fake page?', 'Change the password from the real app now, turn on two-factor, and log out other sessions.'),
  ('Can I report the fake email?', 'You can forward phishing emails to phish@instagram.com, then delete them.')],
 ['Anyone who just received an unexpected email about their Instagram login.', 'Business owners who receive fake copyright or verification emails.', 'People who clicked a link and are worried.'])

page('instagram-hacked-first-hour-checklist', 'ighacked', 'Instagram Hacked: What to Do in the First Hour',
 'The first hour after an Instagram hack matters most. A clear order of steps to undo changes, warn followers and start the official recovery.',
 'Your Instagram was just hacked. What do you do first?', 'Hacked, first hour',
 'Most of what decides a hacked recovery happens early. Work through this list in order.',
 'In the first hour after an Instagram hack, check your email for a message from Instagram about a changed email or password and use its secure link. If that fails, request a login link or security code from the login screen. Warn followers through another channel, secure your email account, and start Instagram’s hacked account recovery.',
 [('Use the security email', 'It can undo the change.'), ('Secure your email first', 'Hackers often have it too.'), ('Warn people', 'Followers may get scam DMs.')],
 [S('The order that works',
    ol(['Search your inbox for emails from mail.instagram.com about a changed email, phone or password. Use the revert link.',
        'Change the password on the email account linked to Instagram and turn on two-factor there.',
        'On the Instagram login screen tap Forgot password, then Need more help or Can’t reset your password, and follow the steps.',
        'If Instagram offers a video selfie, take it in good light. It works best when your face appears in posts on the account.',
        'Tell friends, followers and customers through other channels not to trust DMs from the account.',
        'If the account is linked to Facebook, check the Facebook account too.'])),
  S('Business accounts', 'If the account runs ads, check Ads Manager for new campaigns or payment methods and remove them. Change passwords for any business portfolio admin. See %s.' % A('/instagram-hacked-business-account-with-ads-running/', 'hacked business account with ads running')),
 ],
 [('Should I report the account as hacked from another account?', 'You can, but the strongest route is the recovery flow from the login screen of the hacked account itself.'),
  ('The hacker wants money to give it back. Should I pay?', 'No. Paying rarely gets the account back. Keep the messages and report them. In the US you can report to the FBI’s IC3, in the UK to Action Fraud.'),
  ('Can I get it back if the hacker deleted it?', 'Deleted accounts have a 30-day window in which logging in can cancel the deletion. After that it is usually gone.')],
 ['People in the first hours after a hack.', 'Business owners whose shop account was taken.', 'Parents helping a teenager whose account was hacked.'])

page('instagram-hacked-crypto-scam-posts-on-my-account', 'ighacked', 'Hacked Instagram Posting Crypto or Investment Scams',
 'Your hacked Instagram is posting crypto, investment or giveaway scams. How to stop it, warn followers and recover the account.',
 'Your hacked Instagram is posting crypto or investment scams?', 'Hacked, posting scams',
 'Scam posts from hacked accounts often get the account disabled too. Acting now protects you and your followers.',
 'If your hacked Instagram is posting crypto or investment scams, start recovery from the login screen and use any security email from Instagram to revert changes. Ask friends to report the scam posts, not the whole account. Warn followers elsewhere. If the account is later disabled, say in the appeal that it was hacked, with the date.',
 [('Recover first', 'Undo the hacker’s changes.'), ('Report the posts', 'Not the account itself.'), ('Note the dates', 'For a later appeal.')],
 [S('Steps', ol(['Use the revert link in any email from mail.instagram.com.', 'Start hacked recovery from the login screen.', 'Ask a friend to report the scam posts and stories as scams.',
        'Post a warning from your other channels with the date the hack happened.', 'If anyone sent money, they should contact their bank and report it as fraud.'])),
  S('If the account gets disabled', 'Accounts used for scams are often disabled. In the appeal, say the account was hacked, when, and what you did. See %s.' % A('/instagram-account-disabled-after-hack-appeal/', 'disabled after a hack')),
 ],
 [('Am I responsible for money followers lost?', 'This depends on local law. Tell anyone affected to contact their bank and report it. Keep your own record of the hack.'),
  ('Will the account be deleted?', 'It may be disabled. That can be appealed, especially with a clear account of the hack.'),
  ('Should I report to the police?', 'If money was taken or you are being threatened, yes. In the UK use Action Fraud, in the US the FBI’s IC3 or the FTC.')],
 ['People whose account is posting fake investment or crypto content.', 'Creators whose followers were scammed through their account.', 'Anyone whose friends say they got odd DMs from them.'])

page('report-hacked-account-police-action-fraud-ic3', 'hacked', 'Reporting a Hacked Account: Action Fraud, IC3, FTC',
 'Where to report a hacked Instagram, Facebook or Snapchat account in the US, UK, Canada, Australia and Ireland, and what a report does.',
 'Where should you report a hacked social media account?', 'Report a hack to the authorities',
 'A police or fraud report rarely brings the account back, but it matters when money, extortion or identity theft is involved.',
 'Report a hacked account to the platform first, through its recovery flow. If money was taken, you are being extorted, or your identity is being used, also report to the national fraud service: Action Fraud in the UK, IC3 and the FTC in the US, the Canadian Anti-Fraud Centre, ReportCyber in Australia, and the Gardaí in Ireland.',
 [('Platform first', 'Only the platform can restore access.'), ('Report fraud', 'When money or threats are involved.'), ('Keep the reference', 'Banks and insurers may ask for it.')],
 [S('Where to report',
    ul(['United States: the FBI Internet Crime Complaint Center (ic3.gov), and the FTC at ReportFraud.ftc.gov. If your identity is used, IdentityTheft.gov.',
        'United Kingdom: Action Fraud (England, Wales and Northern Ireland) or Police Scotland on 101.',
        'Canada: the Canadian Anti-Fraud Centre, and your local police.',
        'Australia: ReportCyber through cyber.gov.au, and Scamwatch for scams.',
        'Ireland: your local Garda station.',
        'EU countries: the national police cybercrime unit.'])),
  S('What a report does and does not do',
    'Fraud reports help the authorities link crimes and may be needed for a bank dispute or an insurance claim. They do not usually make the platform restore your account faster. Keep the reference number and mention it if you write to the platform or your bank.'),
  S('What to include', ul(['The account username and platform.', 'The date and time you lost access.', 'Screenshots of any threats or ransom demands.', 'Any payments made, with dates and amounts.'])),
 ],
 [('Will the police get my account back?', 'Usually not. Account access is restored by the platform through its own recovery process.'),
  ('Is it worth reporting if no money was lost?', 'If someone is threatening you or using your identity, yes. Otherwise, the platform report is the main step.'),
  ('A hacker is threatening to leak photos. What do I do?', 'Do not pay. Keep the messages, report to police, and see %s.' % 'our sextortion guide')],
 ['People in the US, UK, Canada, Australia or Ireland whose account was hacked.', 'Businesses that lost money through a hacked account.', 'Anyone being threatened by the person who took the account.'])

page('facebook-hacked-business-portfolio-unknown-admin', 'fblost', 'Unknown Admin Added to Your Meta Business Portfolio',
 'Someone you do not know was added as admin to your Meta business portfolio. How to remove them, secure ad accounts and report the hack.',
 'A stranger was added as admin to your business portfolio?', 'Unknown admin in business portfolio',
 'This is a common sign of a hacked admin profile. Act now, because the new admin can remove you.',
 'If an unknown person is admin on your Meta business portfolio, remove them in Business Settings under People, then check every ad account, Page and payment method for changes. Change the password and two-factor on every admin profile. If you have already been removed, use Meta’s hacked account flow in the Facebook Help Center.',
 [('Remove the admin', 'In Business Settings, People.'), ('Check payment methods', 'Hackers add cards and run ads.'), ('Secure every admin', 'One weak profile is enough.')],
 [S('Steps', ol(['Open Meta Business Settings, then People, and remove the unknown person.', 'Check Ad accounts for new campaigns and pause them.',
        'Check Billing and payments and remove cards you do not recognise.', 'Ask every admin to change their Facebook password and turn on two-factor.',
        'Review Partners and Apps in Business Settings for access you did not grant.'])),
  S('If you were removed', 'If the hacker removed you, use Meta’s hacked account flow from your own profile, then Business Support Home. Keep screenshots of any emails about role changes. See %s.' % A('/guides/meta-business-portfolio-lost-admin-access/', 'lost admin access to a business portfolio')),
 ],
 [('How did they get in?', 'Usually through one admin’s hacked Facebook profile, often after a phishing message pretending to be Meta.'),
  ('Will Meta credit back ads the hacker ran?', 'Meta has a process for unauthorised charges in Billing and payments. Report it there with the dates.'),
  ('Can I stop this happening again?', 'Require two-factor for everyone in Business Settings and keep at least two trusted admins.')],
 ['Business owners and marketing managers who see unknown admins.', 'Agencies managing a client portfolio.', 'Anyone who got an email saying a new admin was added.'])

page('meta-verified-support-how-to-use', 'verified', 'Meta Verified Support: How to Use It for Account Problems',
 'What Meta Verified support can help with, how to open a chat or email, and what it cannot do for a disabled or hacked account.',
 'Does Meta Verified support help when your account has a problem?', 'Meta Verified support',
 'Meta Verified is a paid subscription that includes access to account support. Here is how to use it well.',
 'Meta Verified is a paid Meta subscription that includes a verified badge, impersonation protection and access to account support. Support is opened from the subscribed account, through the Help or Contact support area in Accounts Center. It can help with login, hacked and some restriction problems, but agents cannot override every enforcement decision.',
 [('Open it from the subscribed account', 'Support is tied to that account.'), ('Have the details ready', 'Username, dates and screenshots.'), ('Keep the reference', 'Each chat or email has one.')],
 [S('How to reach support', ol(['Log in to the account that has Meta Verified.', 'Open Accounts Center, then Meta Verified, or the Help section in settings.',
        'Choose the option to contact support, by chat or email, where it is shown.', 'Describe the problem in a few lines, with dates, and attach screenshots.', 'Save the reference number you are given.'])),
  S('What it can and cannot do', ul(['It can guide you through login and hacked account steps.', 'It can pass some restriction or review requests on.', 'It cannot see or act on an account you cannot log into, unless that account is linked to the subscribed one.',
        'It cannot promise reinstatement. Enforcement decisions are reviewed by separate teams.'])),
  S('Related', '%s, %s.' % (A('/meta-verified-account-disabled-support-cannot-help/', 'Meta Verified but disabled'), A('/meta-verified-worth-it-for-account-recovery/', 'is Meta Verified worth it for recovery'))),
 ],
 [('Can I buy Meta Verified on a disabled account?', 'No. The account must be active and in good standing to subscribe.'),
  ('Does Meta Verified prevent bans?', 'No. Verified accounts follow the same rules and can be restricted or disabled.'),
  ('Is Meta Verified available in my country?', 'It is available in many countries, including the US, UK, Canada, Australia and most of the EU. Check the Meta Verified page in Accounts Center.')],
 ['People who pay for Meta Verified and need help with a problem.', 'Businesses deciding whether to subscribe.', 'Creators with a linked account in trouble.'])

page('meta-verified-account-disabled-support-cannot-help', 'verified', 'Meta Verified but Account Disabled: Support Options',
 'You paid for Meta Verified and the account was disabled anyway, or support keeps closing your request. What still works.',
 'You have Meta Verified, the account was disabled, and support is not helping?', 'Verified, disabled, support stuck',
 'This is a common complaint. Support is tied to an active account, so once that account is disabled the routes change.',
 'If your Meta Verified account is disabled, you usually lose support with it, because support is opened from the subscribed account. Use the appeal in the disabled notice. If another account in the same Accounts Center still has Meta Verified, open support from there and mention the disabled account by username and date.',
 [('Use the appeal', 'It is the main route.'), ('Linked account support', 'Open it from an active subscribed account.'), ('Billing separately', 'Stop the subscription if you want.')],
 [S('Routes that still work', ol(['The appeal or request review link in the disabled notice.', 'Support from another active Meta Verified account in the same Accounts Center.',
        'For EU users, a certified out-of-court dispute body once you have a final decision.', 'For UK and EU users, a data access request to Meta.'])),
  S('The subscription', 'Check where you pay: the App Store, Google Play or Meta directly. You can cancel there. Cancellation rules depend on where you bought it.'),
  S('Your rights', 'See %s.' % A(LEG[1], 'your rights when an account is banned')),
 ],
 [('Meta Verified support closed my request with no answer. Can I reopen?', 'You can open a new request from the subscribed account. Reference the old number.'),
  ('Does paying for Meta Verified count in my appeal?', 'Not formally. It shows the account was verified with your ID, which can help explain it is genuine.'),
  ('Can I get the subscription money back?', 'That depends on where you bought it and local consumer rules. Ask the store you paid through.')],
 ['Subscribers whose verified account was disabled.', 'Business owners told by support that nothing can be done.', 'Creators who paid for support and want to know what is left.'])

page('meta-verified-worth-it-for-account-recovery', 'verified', 'Is Meta Verified Worth It for Account Protection?',
 'An honest look at what Meta Verified gives a business or creator: support access, impersonation protection, and what it does not cover.',
 'Is Meta Verified worth paying for to protect your account?', 'Is Meta Verified worth it',
 'It can be useful, especially for businesses. It is not insurance against bans.',
 'Meta Verified can be worth it for businesses and creators who need a support channel and impersonation protection while their account is active. It does not stop bans, and support usually stops if the subscribed account is disabled. Pair it with two-factor, a second admin and a backup email to protect the account properly.',
 [('Good for', 'Support access and impersonation checks.'), ('Not for', 'Stopping enforcement decisions.'), ('Best paired with', 'Two-factor and backup admins.')],
 [S('What you get', ul(['A verified badge after an ID check.', 'Proactive impersonation monitoring.', 'Access to account support by chat or email.', 'For businesses, some plans add extra features.'])),
  S('What protects you more', ol(['An authenticator app for two-factor, with recovery codes saved.', 'A second admin on Pages and business portfolios.', 'A recovery email you control and check.', 'Following the rules on repetitive or automated activity.'])),
 ],
 [('Can Meta Verified get a disabled account back?', 'Not by itself. It gives you a support channel, not a different decision.'),
  ('Should my business subscribe?', 'If losing the account would stop sales, a support channel is useful. Set up the other protections too.'),
  ('Does it help against impersonators?', 'Yes, it includes impersonation monitoring for the verified account.')],
 ['Business owners weighing the subscription.', 'Creators who have been impersonated.', 'Agencies advising clients.'])

page('tiktok-account-banned-appeal', 'tiktok', 'TikTok Account Banned: How to Appeal the Right Way',
 'Your TikTok account is banned or permanently banned. How to find the appeal in the app, what to write, and the EU dispute option.',
 'Your TikTok account is banned. How do you appeal?', 'TikTok account banned',
 'TikTok shows the ban and the appeal inside the app. The wording of the notice tells you which route you have.',
 'To appeal a TikTok ban, open the app, log in, and tap the ban notice. Choose Appeal or Submit an appeal and explain in a few lines why the decision is wrong. You can also use Report a problem in settings. EU users can take a final TikTok decision to Appeals Centre Europe within six months.',
 [('Open the notice', 'The appeal is inside it.'), ('Keep it short', 'Plain facts work best.'), ('EU dispute body', 'Appeals Centre Europe covers TikTok.')],
 [S('Steps', ol(['Log in to TikTok and open the ban notice.', 'Tap Appeal and choose the reason that fits.', 'Write a short explanation: what the account is for and why the decision is wrong.',
        'Check your inbox and the app for TikTok’s reply.', 'If you have no notice, use Settings, Report a problem, Account and profile.'])),
  S('Temporary or permanent', 'TikTok uses feature limits, temporary bans and permanent bans. A permanent ban after repeated violations is harder to overturn, but the appeal is still open where the notice shows it.'),
  S('Outside the app', 'EU users can submit TikTok account suspensions to %s. In the US, the FTC accepts complaints about business practices, but does not resolve individual account decisions.' % A('/appeals-centre-europe-instagram-facebook-suspension/', 'Appeals Centre Europe')),
 ],
 [('How long does a TikTok appeal take?', 'TikTok does not publish a fixed time. Many people hear back within days, some take longer.'),
  ('Can I make a new TikTok account?', 'TikTok’s terms do not allow new accounts to get around a permanent ban.'),
  ('My account was banned for being under 13 but I am older.', 'Use the appeal in the notice. TikTok may ask you to confirm your age with ID or a selfie.')],
 ['TikTok creators and sellers whose account was banned.', 'EU users who want an independent review.', 'Parents helping a teenager.'])

page('tiktok-hacked-account-recovery', 'tiktok', 'TikTok Account Hacked: Recovery Steps That Work',
 'Someone took over your TikTok account. How to reset access, use TikTok support, and secure the email linked to it.',
 'Your TikTok account was hacked. What now?', 'TikTok hacked',
 'Hacked TikTok accounts are recovered through the login screen and TikTok’s support form. Start with your email.',
 'If your TikTok account is hacked, secure the email or phone linked to it first, then use Forgot password on the TikTok login screen. If the hacker changed those details, use the login help form to contact TikTok with your username and proof of ownership, such as when you created the account and the device you used.',
 [('Secure your email', 'Do this before anything else.'), ('Reset from login', 'Forgot password, then follow the steps.'), ('Use TikTok support', 'If your details were changed.')],
 [S('Steps', ol(['Change the password on your email account and turn on two-factor.', 'On the TikTok login screen tap Forgot password and use your phone or email.',
        'If that fails, use the help option on the login screen and say the account was hacked.', 'Give your username, rough creation date, and the phone model you used.', 'Once in, turn on two-step verification and remove unknown devices.'])),
  S('TikTok Shop and creator accounts', 'If the account sells or earns, also check payout details and Shop settings for changes once you are back in.'),
 ],
 [('Will TikTok ask for ID?', 'Sometimes, to confirm ownership. Only provide it through TikTok’s own app or site.'),
  ('Someone is asking for money to return it.', 'Do not pay. Report the messages to TikTok and to your national fraud service.'),
  ('Can Unbanz log in for me?', 'No. Nobody should ask for your login or codes.')],
 ['TikTok users who lost access to a hacker.', 'Sellers and creators with income on the account.', 'Anyone whose TikTok email was changed.'])

page('tiktok-business-account-suspended', 'tiktok', 'TikTok Business or Shop Account Suspended: Next Steps',
 'Your TikTok business account or TikTok Shop was suspended. Where to appeal, what to check, and how to keep selling meanwhile.',
 'Your TikTok business account or shop was suspended?', 'TikTok business suspended',
 'TikTok business accounts, TikTok Shop and TikTok Ads have separate reviews. Find which one is affected first.',
 'When a TikTok business account is suspended, check which part is affected: the account, TikTok Shop through Seller Center, or ads through TikTok Ads Manager. Each has its own appeal. Appeal from the notice, give your business details clearly, and keep orders moving through your website or other channels in the meantime.',
 [('Find the affected part', 'Account, Shop or ads.'), ('Appeal in that tool', 'Each has its own review.'), ('Keep selling elsewhere', 'Your site and email list.')],
 [S('Where to appeal', ul(['Account: the notice in the TikTok app.', 'TikTok Shop: Seller Center, Account health or Violation records.', 'Ads: TikTok Ads Manager, account status.'])),
  S('What helps', ol(['Business registration and a working website.', 'Clear product listings that match TikTok’s policies.', 'A short, factual appeal without repeated submissions.'])),
 ],
 [('Is a Shop suspension the same as an account ban?', 'No. A Shop can be suspended while the account stays active, and the other way round.'),
  ('Can I open a new shop?', 'Not to get around a suspension. It can lead to further action.'),
  ('Does the EU route apply to TikTok Shop?', 'Appeals Centre Europe covers TikTok account and content decisions. Shop decisions may fall under other rules.')],
 ['TikTok sellers and brands.', 'Creators with business accounts.', 'Agencies running TikTok for clients.'])
